// recsJanitorFixture opens a real store with the seeded module registry for
// the recs janitor tests.
func recsJanitorFixture(t *testing.T) (*store.Store, *module.Registry, context.Context) {
	t.Helper()
	ctx := context.Background()
	st, err := store.Open(ctx, filepath.Join(t.TempDir(), "recs.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })
	reg, err := module.Open(ctx, st)
	if err != nil {
		t.Fatalf("module.Open: %v", err)
	}
	return st, reg, ctx
}

// recsDoc builds one persisted document from a raw JSON sources object.
func recsDoc(t *testing.T, sources string) json.RawMessage {
	t.Helper()
	return json.RawMessage(`{"sources": ` + sources + `}`)
}

// TestRecsJanitorLearnsTags drives the full sweep→resolve→apply→stamp joint
// over the real store and the seeded serial/tv module configs: an episode's
// tags come from its SERIES document (the episode document carries none —
// the join), a film's from its own document, tags normalize before the
// weight write, a tag shared by two watches accumulates to 2, the pass
// stamps the queue empty, and a rerun over the drained queue changes
// nothing (idempotent).
func TestRecsJanitorLearnsTags(t *testing.T) {
	st, reg, ctx := recsJanitorFixture(t)

	// The series document is the synopsis carrier: serial-parser's namespace
	// carries facts but NO description (facts alone never claim), shikimori
	// carries the description + genres — the first-carrier winner.
	if err := st.PutSeries(ctx, store.Series{
		ModuleID:     "serial",
		LibraryID:    1,
		RelativePath: "Code Geass",
		Document: recsDoc(t, `{
			"serial-parser": {"season_episode": "S01E01"},
			"shikimori":     {"description": "Нападение Британии", "genres": ["Action", " Драма "]}
		}`),
	}); err != nil {
		t.Fatalf("PutSeries: %v", err)
	}
	// The episode's own document carries NO genres — the series join supplies
	// the tags (spec: "Episode tags come from the series document").
	if err := st.PutItem(ctx, store.Item{
		ID: "it_ep1", ModuleID: "serial", LibraryID: 1, FileID: "f_ep1",
		Document: recsDoc(t, `{"parsed": {"season": 1}}`),
	}); err != nil {
		t.Fatalf("PutItem episode: %v", err)
	}
	// A film/tv item learns from its OWN document's winning namespace.
	if err := st.PutItem(ctx, store.Item{
		ID: "it_film", ModuleID: "tv", LibraryID: 2, FileID: "f_film",
		Document: recsDoc(t, `{"tv-parser": {"description": "d", "genres": ["Action", "Comedy"]}}`),
	}); err != nil {
		t.Fatalf("PutItem film: %v", err)
	}
	now := time.Now()
	if err := st.InsertWatched(ctx, "it_ep1", 1, "Code Geass", now); err != nil {
		t.Fatalf("InsertWatched episode: %v", err)
	}
	if err := st.InsertWatched(ctx, "it_film", 2, "", now); err != nil {
		t.Fatalf("InsertWatched film: %v", err)
	}

	sweep := newRecsSweep(st, reg)
	sweep(ctx)
	want := map[string]int64{"action": 2, "драма": 1, "comedy": 1}
	recsAssertWeights(t, st, want)
	recsAssertQueueEmpty(t, st)

	// The drained queue reruns to the same state — restart-safe/idempotent.
	sweep(ctx)
	recsAssertWeights(t, st, want)
	recsAssertQueueEmpty(t, st)
}

// TestRecsJanitorHonestAbsence pins the honest-absence shapes: an entity
// whose winning namespace carries no genres, a vanished entity (the item row
// deleted since the watch), and an unresolvable module all consume their
// watched rows WITHOUT touching a weight — the queue drains, no tags are
// fabricated, and no resolution failure starves the pass.
func TestRecsJanitorHonestAbsence(t *testing.T) {
	st, reg, ctx := recsJanitorFixture(t)

	// No description in any namespace → no carrier → no tags.
	if err := st.PutItem(ctx, store.Item{
		ID: "it_plain", ModuleID: "tv", LibraryID: 1, FileID: "f_plain",
		Document: recsDoc(t, `{"tv-parser": {"genres": ["Never"], "title": "t"}}`),
	}); err != nil {
		t.Fatalf("PutItem plain: %v", err)
	}
	if err := st.InsertWatched(ctx, "it_plain", 1, "", time.Now()); err != nil {
		t.Fatalf("InsertWatched plain: %v", err)
	}
	// A vanished entity and an unresolvable module: consumed with absence.
	if err := st.InsertWatched(ctx, "it_ghost", 1, "", time.Now()); err != nil {
		t.Fatalf("InsertWatched ghost: %v", err)
	}
	if err := st.InsertWatched(ctx, "it_orphan", 1, "", time.Now()); err != nil {
		t.Fatalf("InsertWatched orphan: %v", err)
	}
	if err := st.PutItem(ctx, store.Item{
		ID: "it_orphan", ModuleID: "no-such-module", LibraryID: 1, FileID: "f_orphan",
		Document: recsDoc(t, `{}`),
	}); err != nil {
		t.Fatalf("PutItem orphan: %v", err)
	}

	newRecsSweep(st, reg)(ctx)
	recsAssertWeights(t, st, map[string]int64{})
	recsAssertQueueEmpty(t, st)
}

// TestRecsJanitorWakeRunsPass covers the registry wake mechanics plus the
// task's boot-run: the recs task boot-runs once despite the hour interval,
// a notifyRecs poke runs a pass WITHOUT waiting out the tick, and the loop
// exits on ctx cancel.
func TestRecsJanitorWakeRunsPass(t *testing.T) {
	// Drain any wake a prior poke left pending — this test counts its own.
drain:
	for {
		select {
		case <-recsWake:
		default:
			break drain
		}
	}
	var passes atomicCounter
	j := newJanitor(janitorTask{
		name: "recs", interval: time.Hour, wake: recsWake,
		fn: func(context.Context) { passes.add(1) },
	})
	j.runBoot(context.Background())
	if got := passes.load(); got != 1 {
		t.Fatalf("boot-run: recs ran %d times, want 1", got)
	}

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	done := make(chan struct{})
	go func() {
		defer close(done)
		j.run(ctx)
	}()
	notifyRecs()
	deadline := time.Now().Add(2 * time.Second)
	for passes.load() < 2 {
		if time.Now().After(deadline) {
			t.Fatalf("wake: recs ran %d times within 2s of the poke, want >= 2", passes.load())
		}
		time.Sleep(time.Millisecond)
	}
	cancel()
	<-done
}

// recsAssertWeights asserts the learned tag_weights table equals want
// (normalized keys → weights) via the store's own read.
func recsAssertWeights(t *testing.T, st *store.Store, want map[string]int64) {
	t.Helper()
	tags, weights, err := st.ListTagWeights(context.Background())
	if err != nil {
		t.Fatalf("ListTagWeights: %v", err)
	}
	if len(tags) != len(want) {
		t.Fatalf("tag weights = %v (keys %d), want %d keys %v", tags, len(tags), len(want), want)
	}
	for i, tag := range tags {
		if weights[i] != want[tag] {
			t.Fatalf("weight[%s] = %d, want %d", tag, weights[i], want[tag])
		}
	}
}

// recsAssertQueueEmpty asserts the derived learning queue is drained: every
// watched row is stamped applied.
func recsAssertQueueEmpty(t *testing.T, st *store.Store) {
	t.Helper()
	itemIDs, _, _, _, err := st.ListUnappliedWatched(context.Background())
	if err != nil {
		t.Fatalf("ListUnappliedWatched: %v", err)
	}
	if len(itemIDs) != 0 {
		t.Fatalf("unapplied watched = %v, want empty (queue must be stamped)", itemIDs)
	}
}
